#include <bitset>
#include <string>

int main() {
    // Example 1: Full string, truncation (N=5 < 7 chars)
    // Result: 10101 (The first two '10' are ignored)
    std::bitset<5> b1(std::string("1010101"));

    // Example 2: Substring (start at index 2, length 3)
    // "1111000" -> substring "110" -> Result: 00110 (Padded with leading zeros)
    std::bitset<7> b2(std::string("1111000"), 2, 3);

    // Example 3: Implicit conversion pitfall workaround
    // bitset<8> b3("1010"); // ERROR (No implicit const char* to string)
    std::bitset<8> b3(std::string("1010")); // OK
}
